insert into public.heroes (id, sort_order, name, known_as, origin_city, origin_province, region_group, birth_date, birth_place, death_date, death_place, age_at_death, photo_path, short_bio, full_bio, struggle_era, famous_quote, quote_context, decree_number, burial_place) values
  ('soekarno', 1, 'Ir. Soekarno', 'Bung Karno / Bapak Proklamator', 'Surabaya', 'Jawa Timur', 'Jawa', '6 Juni 1901', 'Surabaya, Jawa Timur', '21 Juni 1970', 'Jakarta', 69, 'assets/images/soekarno.jpg', 'Presiden pertama Republik Indonesia dan Proklamator Kemerdekaan Indonesia bersama Mohammad Hatta. Bung Karno merupakan penggali dasar negara Pancasila serta orator ulung yang menggerakkan persatuan bangsa.', 'Ir. Soekarno lahir di Surabaya pada 6 Juni 1901 dengan nama Kusno Sosrodihardjo. Beliau menempuh pendidikan teknik sipil di Technische Hoogeschool te Bandoeng (kini ITB). Sejak muda, Soekarno aktif dalam gerakan pergerakan nasional mendirikan Partai Nasional Indonesia (PNI) pada tahun 1927.
