insert into public.quiz_questions (id, sort_order, hero_id, question, correct_index, explanation) values
  ('q1', 1, 'soekarno', 'Di kota manakah Ir. Soekarno dilahirkan pada tanggal 6 Juni 1901?', 1, 'Ir. Soekarno lahir di Surabaya, Jawa Timur pada 6 Juni 1901, sebelum kemudian menempuh pendidikan di Mojokerto dan Bandung.'),
  ('q2', 2, 'hatta', 'Gelar kehormatan apakah yang disematkan kepada Bung Hatta atas jasa besarnya dalam ekonomi kerakyatan?', 1, 'Bung Hatta dijuluki sebagai Bapak Koperasi Indonesia berkat jasanya merumuskan prinsip ekonomi kekeluargaan dan koperasi.'),
  ('q3', 3, 'kartini', 'Buku kumpulan surat R.A. Kartini yang sangat terkenal berjudul...', 0, 'Buku surat korespondensi R.A. Kartini diterbitkan oleh J.H. Abendanon dengan judul "Door Duisternis tot Licht" yang diterjemahkan menjadi "Habis Gelap Terbitlah Terang".'),
  ('q4', 4, 'soedirman', 'Pertempuran heroik apakah yang dipimpin Soedirman hingga diperingati sebagai Hari Juang Kartika TNI AD?', 1, 'Kemenangan gemilang di Palagan Ambarawa pada 15 Desember 1945 mengabadikan nama Soedirman dan diperingati sebagai Hari Juang Kartika TNI AD.'),
  ('q5', 5, 'ki_hajar_dewantara', 'Lembaga pendidikan nasional yang didirikan Ki Hajar Dewantara pada tahun 1922 adalah...', 1, 'Ki Hajar Dewantara mendirikan Nationaal Onderwijs Instituut Tamansiswa di Yogyakarta pada 3 Juli 1922.'),
  ('q6', 6, 'hasanuddin', 'Sultan Hasanuddin dari Kerajaan Gowa dijuluki oleh pihak Belanda sebagai...', 1, 'Belanda menjuluki Sultan Hasanuddin "De Haantjes van Het Oosten" (Ayam Jantan dari Timur) karena keberaniannya menentang monopoli VOC.'),
  ('q7', 7, 'pattimura', 'Benteng pertahanan Belanda yang berhasil direbut oleh Kapitan Pattimura di Pulau Saparua adalah...', 1, 'Pada Mei 1817, Kapitan Pattimura memimpin penyerbuan dan berhasil merebut Benteng Duurstede di Saparua, Maluku.'),
  ('q8', 8, 'frans_kaisiepo', 'Tokoh pahlawan nasional asal Papua yang mengusulkan nama "IRIAN" pada Konferensi Malino 1946 adalah...', 1, 'Frans Kaisiepo mempopulerkan akronim IRIAN (Ikut Republik Indonesia Anti Nederland) pada Konferensi Malino 1946.'),
  ('q9', 9, 'bung_tomo', 'Bung Tomo membakar semangat juang arek-arek Suroboyo dalam pertempuran yang kini diperingati sebagai Hari Pahlawan pada tanggal...', 2, 'Pertempuran heroik Surabaya pada 10 November 1945 diperingati sebagai Hari Pahlawan Nasional Indonesia.'),
  ('q10', 10, 'dewi_sartika', 'Sekolah kejuruan khusus perempuan yang didirikan Raden Dewi Sartika di Bandung pada tahun 1904 adalah...', 1, 'Raden Dewi Sartika mendirikan Sakola Istri pada 16 Januari 1904 di Pendopo Kabupaten Bandung.');
